// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Graf kuramı uygulamaları, BFS/DFS, en kısa yol, en küçük kapsayan ağaç, açgözlü (greedy) ve dinamik programlama senaryoları (zor).
const ozComputing17Zor = <(String, String, List<String>, String)>[
  ('Basit ve yönsüz V düğümlü (V ≥ 2) herhangi bir grafta her zaman dereceleri birbirine eşit en az iki düğüm bulunmasının nedeni nedir?', '0 ile V-1 dereceli düğümün aynı anda var olamaması ve güvercin yuvası ilkesi', ['El sıkışma lemmasına göre toplam derecenin her zaman asal sayı çıkması', 'Komşuluk matrisinin determinantının her zaman sıfıra eşit olması', 'Her yönsüz grafın mutlaka en az bir adet üçgen çevrim içermesi'], 'Olası dereceler 0..V-1 arasındadır ancak V-1 dereceli düğüm herkese bağlı olduğundan 0 dereceli düğümle birlikte bulunamaz; V düğüm V-1 olası değere dağılır.'),
  ('Düzlemsel, bağlı bir grafta 10 düğüm ve 16 kenar varsa Euler düzlemsel graf formülüne göre (dış bölge dahil) kaç bölge (yüz) vardır?', '8', ['6', '10', '26'], 'Euler formülü V - E + F = 2 şeklindedir; 10 - 16 + F = 2 eşitliğinden F = 8 bölge bulunur.'),
  ('Dereceleri yalnızca 3 ve 5 olan düğümlerden oluşan 18 kenarlı yönsüz bir grafta 3 dereceli 7 düğüm varsa, 5 dereceli kaç düğüm vardır?', '3', ['5', '4', '6'], 'Toplam derece 2 × 18 = 36\'dır; 3 dereceli 7 düğüm 21 derece sağlar, kalan 36 - 21 = 15 derece için 15 / 5 = 3 adet 5 dereceli düğüm gerekir.'),
  ('V düğümlü ve E kenarlı yönsüz basit bir grafın komşuluk matrisindeki 0 (sıfır) elemanlarının sayısı kaçtır?', 'V² - 2E', ['V² - E', '2E - V', 'V(V - 1) - E'], 'V² hücrenin 2E tanesi kenarları temsil eden 1\'lerden oluşur; geriye kalan V² - 2E hücre (köşegen dahil) 0\'dır.'),
  ('V = 1000 düğümlü bir grafta her hücre 4 bayt yer kaplayan tam sayı komşuluk matrisi yerine, her kenar kaydı 8 bayt ve her liste başlığı 8 bayt olan komşuluk listesi kullanıldığında yönsüz graf için yaklaşık kaç kenarın altında liste daha az bellek harcar?', 'Yaklaşık 249.500 kenar', ['Yaklaşık 499.000 kenar', 'Yaklaşık 125.000 kenar', 'Yaklaşık 10.000 kenar'], 'Matris 10⁶ × 4 = 4.000.000 bayt harcar; listede 8V + 16E < 4.000.000 eşitsizliğinden 8000 + 16E < 4.000.000 yani E < 249.500 bulunur.'),
  ('Havel-Hakimi algoritmasına göre (4, 3, 3, 2, 2, 1) dizisinin basit bir yönsüz grafa ait olamamasının temel nedeni nedir?', 'Dereceler toplamının 15 gibi tek bir sayı olması', ['En büyük derecenin düğüm sayısından küçük olması', 'Dizide birden fazla tekrar eden sayı bulunması', 'En küçük derecenin sıfırdan farklı bir değer olması'], '4 + 3 + 3 + 2 + 2 + 1 = 15 tek sayıdır; el sıkışma lemması gereği derece toplamı tek olan hiçbir basit yönsüz graf çizilemez.'),
  ('(5, 5, 4, 3, 2, 1) derece dizisi Havel-Hakimi indirgemesiyle incelendiğinde basit bir yönsüz graf oluşturur mu?', 'Oluşturmaz, indirgeme sonunda negatif derece ortaya çıkar', ['Oluşturur, çünkü dereceler toplamı 20 yani çift sayıdır', 'Oluşturur, çünkü en büyük derece düğüm sayısından küçüktür', 'Oluşturmaz, çünkü kenar sayısı düğüm sayısının altında kalır'], '6 düğümlü basit grafta 5 dereceli iki düğüm diğer tüm düğümlere bağlı olmalıdır; oysa bu durumda 1 dereceli düğüm en az iki düğüme bağlanmak zorunda kalacağından graf çizilemez.'),
  ('Yönsüz basit bir grafta tüm düğümlerin derecesi en az 2 ise bu graf hakkında aşağıdakilerden hangisi kesinlikle doğrudur?', 'En az bir çevrim içerir', ['Kesinlikle bağlı bir graftır', 'Kesinlikle iki parçalı bir graftır', 'Düğüm sayısı çift bir sayıdır'], 'Sonlu bir grafta her düğümün derecesi ≥ 2 ise en uzun basit yolun uç düğümünün tüm komşuları yol üzerindedir ve bu durum en az bir çevrim oluşturur.'),
  ('Bir yönsüz ağacın 6 düğümünün derecesi 1 (yaprak), 3 düğümünün derecesi 2 ve kalan tek düğümünün derecesi k ise k kaçtır?', '6', ['4', '5', '3'], 'Toplam düğüm sayısı V = 6 + 3 + 1 = 10\'dur; ağaçta 9 kenar ve 18 toplam derece vardır: (6×1) + (3×2) + k = 18 eşitliğinden 12 + k = 18 yani k = 6 bulunur.'),
  ('Yönlü basit bir G grafının komşuluk matrisi A simetrik çıkıyorsa bu graf hakkında ne söylenebilir?', 'Her (u, v) yönlü kenarı için karşıt yönlü (v, u) kenarı da mevcuttur', ['Graf hiçbir yönlü çevrim içermeyen bir ağaç yapısındadır', 'Graftaki tüm düğümlerin giriş derecesi sıfıra eşittir', 'Grafın kenar sayısı düğüm sayısının tam iki katına eşittir'], 'A[u][v] = A[v][u] eşitliği, u\'dan v\'ye kenar olan her durumda v\'den u\'ya da kenar bulunduğunu gösterir.'),
  ('Kenarları ağırlıklı olan bir grafta komşuluk listesi kullanıldığında her liste düğümünde hangi iki bilginin birlikte tutulması zorunludur?', 'Hedef komşu düğüm kimliği ve o kenarın ağırlık değeri', ['Grafın toplam düğüm sayısı ve başlangıç düğümü derecesi', 'Komşuluk matrisinin boyutu ve önceki düğümün bellek adresi', 'En kısa yolun toplam uzunluğu ve bağlı bileşen sayısı'], 'Komşuluk listesinde kaynak düğüm zaten bilindiğinden, listedeki her kayıtta gidilen komşu düğümün numarası ve aradaki kenarın ağırlığı saklanır.'),
  ('Düğümleri 1\'den 12\'ye kadar numaralandırılmış bir grafta yalnızca i + j toplamı çift sayı olduğunda i ile j arasına kenar konulursa (i ≠ j), oluşan graf kaç bağlı bileşene sahiptir ve kaç kenarlıdır?', '2 bağlı bileşen ve 30 kenar', ['1 bağlı bileşen ve 66 kenar', '2 bağlı bileşen ve 36 kenar', '3 bağlı bileşen ve 24 kenar'], 'Tek sayılar kendi aralarında (6 düğüm: 6×5/2 = 15 kenar) ve çift sayılar kendi aralarında (6 düğüm: 15 kenar) tam graf oluşturur; tek ile çift arasında kenar olmadığından 2 bileşen ve 30 kenar vardır.'),
  ('Yönlü çevrimsiz bir grafta (DAG) en az bir düğümün giriş derecesinin 0 ve en az bir düğümün çıkış derecesinin 0 olmasının nedeni nedir?', 'Sonlu düğüm kümesinde çevrim olmadığından geriye ve ileriye gidişin bir noktada durması', ['Yönlü graflarda el sıkışma lemmasının yalnızca çift dereceli düğümlerde çalışması', 'Her yönlü çevrimsiz grafın aynı zamanda tam iki parçalı bir graf olması', 'Komşuluk matrisindeki köşegen elemanlarının toplamının kenar sayısını vermesi'], 'Sonlu bir grafta her düğümün çıkış derecesi ≥ 1 olsaydı sonsuza dek ilerlenir ve güvercin yuvası ilkesiyle bir düğüm tekrar edilerek çevrim oluşurdu.'),
  ('V düğümlü yönsüz bir grafta hiç üçgen (3 uzunluklu çevrim) bulunmuyorsa Mantel teoremine göre bu grafta en fazla kaç kenar olabilir?', '⌊V² / 4⌋', ['V(V - 1) / 2', '2V - 3', '⌊V² / 2⌋'], 'Mantel teoremine göre üçgen içermeyen V düğümlü basit bir grafta maksimum kenar sayısı tam iki parçalı dengeli grafta elde edilir ve ⌊V² / 4⌋ olur.'),
  ('Mantel teoremine göre 10 düğümlü ve içinde hiç 3 uzunluklu çevrim (üçgen) barındırmayan basit bir yönsüz grafta en fazla kaç kenar bulunabilir?', '25', ['45', '20', '30'], 'Düğümler 5 ve 5 olarak iki parçalı tam graf (K₅,₅) şeklinde ayrıldığında üçgen oluşmaz ve en fazla 5 × 5 = 25 kenar elde edilir.'),
  ('Komşuluk listesinde her düğümün komşuları sırasız bağlı liste yerine dengeli ikili arama ağacı (veya sıralı dizi) ile tutulursa, (u, v) kenar sorgusunun en kötü durum karmaşıklığı nasıl değişir?', 'O(derece(u)) değerinden O(log(derece(u))) değerine düşer', ['O(V) değerinden O(V²) değerine yükselir', 'O(1) sabit zamanından O(E) zamanına yükselir', 'Hiçbir değişiklik olmaz, yine O(V + E) olarak kalır'], 'Komşular sıralı veya dengeli ağaç yapısında tutulduğunda doğrusal arama yerine ikili arama yapılarak sorgu süresi logaritmik düzeye iner.'),
  ('Bir yönsüz ağacın en az iki düğümü varsa (V ≥ 2), bu ağaçta derecesi 1 olan (yaprak) en az kaç düğüm bulunmak zorundadır?', '2', ['1', '3', '4'], 'Çevrimsiz ve bağlı olan V ≥ 2 düğümlü bir ağaçta en uzun basit yolun her iki uç noktası da başka yeni düğüme uzanamayacağı ve geri dönemeyeceği için en az 2 yaprak vardır.'),
  ('20 düğümlü bir yönsüz grafta her düğümün derecesi en az 10 ise bu grafın bağlı bileşen sayısı kaçtır?', '1', ['2', '3', '10'], 'Her düğümün derecesi ≥ (V-1)/2 (burada 10 > 9.5) olduğundan herhangi iki düğüm ya komşudur ya da ortak komşuya sahiptir; graf kesinlikle bağlıdır (1 bileşen).'),
  ('Komşuluk matrisi A olan yönsüz basit bir grafta A³ matrisinin ana köşegen elemanlarının toplamının (iz / trace) 6\'ya bölünmesi neyi verir?', 'Graftaki 3 uzunluklu çevrimlerin (üçgenlerin) sayısını', ['Graftaki toplam bağlı bileşenlerin sayısını', 'Graftaki maksimum dereceli düğümün kenar sayısını', 'Graftaki köprü niteliğindeki kenarların sayısını'], 'Her üçgen 3 köşesinde de iki farklı yönde (saat yönü ve tersi) 3 adımlık kapalı yürüyüş üretir; bu yüzden iz(A³) / 6 üçgen sayısına eşittir.'),
  ('Yönlü bir grafta (u, v) kenarının DFS zaman damgaları d[u] < d[v] < f[v] < f[u] eşitsizliğini sağlıyor ancak (u, v) bir ağaç kenarı değilse bu kenar ne tür bir kenardır?', 'İleri kenar (forward edge)', ['Geri kenar (back edge)', 'Çapraz kenar (cross edge)', 'Köprü kenarı (bridge edge)'], 'Zaman aralığı v\'nin u\'nun alt soyu olduğunu gösterir; u\'dan öz alt soyu v\'ye doğrudan giden fakat DFS ağacında yer almayan kenar ileri kenardır.'),
  ('Yönlü bir grafta (u, v) kenarı incelendiğinde d[v] < d[u] < f[u] < f[v] zaman damgası ilişkisi geçerliyse bu kenar kesinlikle hangi sınıfa girer?', 'Geri kenar (back edge)', ['İleri kenar (forward edge)', 'Çapraz kenar (cross edge)', 'Ağaç kenarı (tree edge)'], 'v düğümü u\'dan önce açılmış ve u kapanana kadar kapanmamıştır, yani v düğümü u\'nun aktif atasıdır; u\'dan atası v\'ye giden kenar geri kenardır.'),
  ('Yönlü bir grafta (u, v) kenarı için d[v] < f[v] < d[u] < f[u] zaman ilişkisi gözlemleniyorsa bu kenar hangi türdedir?', 'Çapraz kenar (cross edge)', ['Geri kenar (back edge)', 'İleri kenar (forward edge)', 'Ağaç kenarı (tree edge)'], 'v düğümü u henüz keşfedilmeden önce hem açılmış hem de tamamen kapanmıştır; ayrık zaman aralıkları arasındaki (u, v) kenarı çapraz kenardır.'),
  ('1\'den başladığı kabul edilen DFS zaman sayacında 4 düğümlü bir yönlü grafta A\'dan başlayan aramada zaman aralıkları A:[1,8], B:[2,5], C:[3,4], D:[6,7] olarak çıkmışsa (D, B) kenarı hangi tür kenardır?', 'Çapraz kenar', ['Geri kenar', 'İleri kenar', 'Ağaç kenarı'], 'B\'nin aralığı [2,5], D\'nin aralığı [6,7]\'dir; d[B] < f[B] < d[D] < f[D] sağlandığından D\'den daha önce bitmiş B dalına giden (D, B) kenarı çapraz kenardır.'),
  ('Tarjan\'ın köprü (bridge) bulma algoritmasında, DFS ağacındaki bir (u, v) ağaç kenarının köprü olması için disc[u] (keşif zamanı) ve low[v] (v alt ağacından en erken erişilebilir ata zamanı) hangi koşulu sağlamalıdır?', 'low[v] > disc[u]', ['low[v] < disc[u]', 'low[v] = 0', 'disc[u] > disc[v]'], 'v\'nin alt ağacından u\'ya veya u\'nun bir atasına hiçbir geri kenar çıkmıyorsa low[v] > disc[u] olur ve (u, v) kenarı silindiğinde v alt ağacı kopar (köprüdür).'),
  ('Tarjan algoritmasında DFS ağacının kök düğümünün bir "eklem noktası" (articulation point) olabilmesi için gerekli ve yeterli koşul nedir?', 'DFS ağacında en az 2 ayrı çocuğa sahip olması', ['Graftaki derecesinin en az 2 olması', 'Kendisine dönen en az bir geri kenar bulunması', 'Keşif zamanının bitiş zamanına eşit olması'], 'Yönsüz grafta çapraz kenar olmadığından, DFS kökünün birden fazla çocuğu varsa bu alt ağaçlar arasında kök dışında bağlantı yoktur; kök silinirse bileşen sayısı artar.'),
  ('Kenar ağırlıkları yalnızca 1 veya 2 olan yönlü bir grafta Dijkstra algoritması ve öncelik kuyruğu kullanmadan standart bir kuyruk (BFS) ile O(V + E) zamanda en kısa yol nasıl bulunabilir?', 'Ağırlığı 2 olan her kenarın ortasına yapay bir ara düğüm ekleyerek iki adet 1 ağırlıklı kenara bölmek', ['Tüm kenar ağırlıklarını 2 ile çarpıp komşuluk matrisinde özyinelemeli DFS çalıştırmak', 'Ağırlığı 2 olan tüm kenarları graftan silip yalnızca 1 ağırlıklı kenarlarla BFS yapmak', 'Kuyruğa yalnız çift dereceli düğümleri ekleyip tek dereceli düğümleri tamamen atlamak'], '2 ağırlıklı her (u, v) kenarı u -> w -> v şeklinde yapay bir düğümle iki birim kenara bölündüğünde graf O(V + E) boyutlu ağırlıksız grafa dönüşür ve BFS tam sonuç verir.'),
  ('Aşamalı Derinleşmeli DFS (IDDFS) algoritması, sığ ama dallanma faktörü b yüksek olan ağaçlarda BFS ve standart DFS\'nin hangi avantajlarını birleştirir?', 'BFS\'nin en kısa (sığ) çözümü bulma garantisi ile DFS\'nin O(b × d) yerine O(d) doğrusal bellek verimliliğini', ['DFS\'nin ağırlıklı graflarda en kısa yolu bulması ile BFS\'nin O(1) zaman karmaşıklığını', 'Komşuluk matrisinin hızlı kenar sorgusu ile komşuluk listesinin simetri özelliğini', 'Topolojik sıralamanın çevrim çözme yeteneği ile el sıkışma lemmasının derece hesabını'], 'IDDFS derinlik sınırını 0, 1, 2... diye artırarak DFS yapar; böylece BFS gibi d derinliğindeki en yakın hedefi bulurken yalnız O(d) yığın belleği harcar.'),
  ('Yönsüz bir grafın iki parçalı (bipartite) olması ile bu grafta yürütülen BFS katmanları arasındaki kesin ilişki aşağıdakilerden hangisidir?', 'BFS\'de aynı katmandaki hiçbir iki düğüm arasında kenar yoksa graf iki parçalıdır', ['BFS ağacının toplam yüksekliği çift sayı çıkıyorsa graf kesinlikle iki parçalıdır', 'BFS kuyruğuna giren düğüm sayısı kenar sayısına eşitse graf iki parçalıdır', 'BFS sırasında her düğümün en az iki çocuğu oluyorsa graf iki parçalıdır'], 'Yönsüz grafta BFS katman dışı kenarlar ya ardışık katmanlar (fark 1) ya da aynı katman (fark 0) arasındadır; aynı katman kenarı tek çevrim üretir, yoksa graf iki parçalıdır.'),
  ('Bağlı ve yönsüz V düğümlü bir G grafında E = V eşitliği biliniyorsa, bu graf üzerinde yapılan tam bir DFS taramasında kaç adet geri kenar (back edge) bulunur ve graf kaç çevrim içerir?', '1 geri kenar ve tam 1 basit çevrim', ['0 geri kenar ve 0 çevrim', '2 geri kenar ve 3 basit çevrim', 'V - 1 geri kenar ve 2 basit çevrim'], 'Bağlı grafta DFS kapsayan ağacı V - 1 ağaç kenarı kullanır; geriye V - (V - 1) = 1 adet geri kenar kalır ve ağaca eklenen tek kenar tam 1 basit çevrim oluşturur.'),
  ('Yönlü bir G grafında u\'dan v\'ye yol var ve v\'den u\'ya yol yok ise (ayrı güçlü bağlı bileşenler), herhangi bir DFS çalıştırmasında bu iki bileşenin maksimum bitiş zamanları hakkında ne kesinlikle doğrudur?', 'u\'nun bileşenindeki maksimum DFS bitiş zamanı, v\'nin bileşenindekinden her zaman büyüktür', ['v\'nin bileşenindeki maksimum DFS bitiş zamanı, u\'nun bileşenindekinden her zaman büyüktür', 'Her iki bileşenin de maksimum bitiş zamanları birbirine tam olarak eşittir', 'Başlangıç düğümünün seçimine göre bazen u\'nunki bazen v\'ninki büyük çıkar'], 'İlk hangi bileşene girilirse girilsin, u bileşeninden v bileşenine geçiş olduğu ama dönüş olmadığı için v bileşeni tamamen kapanmadan u bileşeni tamamen kapanamaz.'),
  ('Döngüsel (iteratif) DFS yazılırken düğümler yığına eklendiği anda "ziyaret edildi" diye işaretlenirse, özyinelemeli standart DFS\'den nasıl bir yapısal sapma oluşabilir?', 'Derindeki bir düğüm yığının altında beklerken sığ seviyeden işaretlendiği için oluşturulan ağaç gerçek DFS ağacı olmayabilir', ['Algoritma bazı bağlı düğümlere hiçbir zaman ulaşamayıp erken sonlanabilir', 'Zaman karmaşıklığı O(V + E) seviyesinden üstel O(2^V) seviyesine çıkabilir', 'Yönsüz graflarda yığın yapısı otomatik olarak öncelik kuyruğuna dönüşebilir'], 'Başlangıç düğümünün tüm komşuları hemen ziyaret edildi sayılırsa derin bir dal o komşulara alttan ulaştığında onları atlar; ağaç BFS-DFS melezi bir yapıya kayar.'),
  ('Çift yönlü BFS (Bidirectional BFS), dallanma faktörü b ve kaynak-hedef uzaklığı d olan bir grafta arama uzayını yaklaşık O(b^d) değerinden hangi mertebeye indirger?', 'O(b^(d/2))', ['O(d × log b)', 'O(b²)', 'O(b + d)'], 'Hem kaynaktan ileri hem hedeften geriye eşzamanlı BFS yürütüldüğünde iki arama ortada (d/2 derinliğinde) buluşur ve incelenen düğüm sayısı 2 × b^(d/2) mertebesine düşer.'),
  ('Dallanma faktörü b = 10 olan düzenli bir arama grafında kaynaktan 6 kenar uzaklıktaki hedefe ulaşmak için tek yönlü BFS yaklaşık 10⁶ düğüm genişletirken, çift yönlü BFS yaklaşık kaç düğüm mertebesinde buluşur?', 'Yaklaşık 2.000 düğüm (2 × 10³)', ['Yaklaşık 500.000 düğüm (5 × 10⁵)', 'Yaklaşık 60 düğüm (6 × 10)', 'Yaklaşık 100 düğüm (10²)'], 'İki uçtan 3\'er katman ilerlenerek ortada buluşulacağından her iki arama yaklaşık 10³ = 1.000 düğüm, toplamda yaklaşık 2.000 düğüm genişletir.'),
  ('Yönsüz bağlı bir G grafında tek bir r düğümünden yapılan BFS ağacı ile aynı r düğümünden yapılan DFS ağacının birebir aynı kenar kümesine sahip olduğu biliniyorsa ve grafta ek kenar varsa dikkat edildiğinde, G\'de hiç çevrim yoksa (G bir ağaçsa) bu durum neden her zaman gerçekleşir?', 'Ağaçta iki düğüm arasında tek bir basit yol bulunduğundan her kapsayan ağaç G\'nin kendisine eşit olur', ['Ağaçlarda kuyruk ve yığın veri yapılarının bellekte aynı fiziksel adresi paylaşması nedeniyle', 'Ağaç yapılarında tüm düğümlerin derecesi birbirine eşit ve çift sayı olduğu için', 'Komşuluk matrisinin ağaçlarda birim matrise eşit olması sebebiyle'], 'G zaten V - 1 kenarlı bir ağaç ise içinden seçilebilecek tek bağlı kapsayan alt graf G\'nin kendisidir; hem BFS hem DFS ağacı aynı V - 1 kenarı içerir.'),
  ('Yönsüz basit ve bağlı bir G grafında seçilen r kökünden başlatılan DFS ağacı ile BFS ağacı karşılaştırıldığında, G\'de r\'ye komşu olan tüm kenarların kesinlikle yer aldığı ağaç hangisidir?', 'BFS ağacı', ['DFS ağacı', 'Yalnızca minimum kapsayan ağaç', 'Sadece maksimum dereceli kapsayan ağaç'], 'r\'den başlayan BFS ilk adımda r\'nin tüm doğrudan komşularını 1. katman olarak r üzerinden keşfettiği için r\'ye bağlı tüm kenarlar BFS ağacındadır; DFS\'de ise komşulara alt dallardan dolanılarak ulaşılabilir.'),
  ('6 düğümlü bir C₆ çevrim grafında (1-2-3-4-5-6-1) 1 numaralı düğümden başlayan BFS ve DFS ağaçlarının yükseklikleri (kökten en uzak yaprağa kenar sayısı) sırasıyla kaçtır?', 'BFS ağacı yüksekliği 3, DFS ağacı yüksekliği 5', ['BFS ağacı yüksekliği 5, DFS ağacı yüksekliği 3', 'Her iki ağacın yüksekliği de 3', 'Her iki ağacın yüksekliği de 6'], 'BFS iki koldan (1-2-3-4 ve 1-6-5) paralel yayılıp 4. düğüme 3 adımda ulaşır (yükseklik 3); DFS ise çevrimi tek koldan (1-2-3-4-5-6) boydan boya dolanır (yükseklik 5).'),
  ('Euler yürüyüşü (her kenardan tam bir kez geçen yürüyüş) varlığını yönsüz bir grafta doğrulamak için derece kontrolünün (0 veya 2 tek dereceli düğüm) yanı sıra neden mutlaka bir BFS veya DFS yapılması gerekir?', 'Derecesi sıfırdan büyük olan tüm düğümlerin tek bir bağlı bileşende yer aldığını doğrulamak için', ['Çift dereceli düğümlerin komşuluk matrisinde köşegen üzerinde sıralandığını kanıtlamak için', 'Graftaki kenar ağırlıklarının negatif sayı içermediğini kontrol etmek amacıyla', 'Grafta hiçbir 3 uzunluklu çevrim bulunmadığını Mantel teoremiyle test etmek için'], 'Örneğin birbirinden kopuk iki ayrı üçgen grafta tüm düğümlerin derecesi 2 (çift) olmasına rağmen kenarlar tek seferde gezilemez; aktif düğümlerin bağlılığı BFS/DFS ile denetlenmelidir.'),
  ('Yönlü bir grafta her düğümün çıkış derecesi tam olarak 1 ise (fonksiyonel graf) ve V düğüm varsa, bu graf üzerinde yürütülen tam bir çevrim saptama algoritması hakkında ne söylenebilir?', 'Her bağlı bileşende tam olarak 1 adet yönlü çevrim bulunur', ['Grafta hiçbir yönlü çevrim bulunması mümkün değildir', 'Graf kesinlikle tek bir güçlü bağlı bileşenden oluşur', 'Toplam kenar sayısı düğüm sayısının iki katına eşittir'], 'V düğümlü fonksiyonel grafta her bileşende düğüm sayısı kadar yönlü kenar vardır; her düğümden tek çıkış olduğundan izlenen yol eninde sonunda kendine bağlanarak bileşen başına tam 1 yönlü çevrim üretir.'),
  ('Büyük ölçekli bir web örümceğinde (web crawler) başlangıç tohum sayfalarından dış bağlantıları tararken saf DFS yerine BFS tabanlı kuyruk mimarisinin tercih edilmesinin en önemli pratik nedeni nedir?', 'Tek bir sitenin derin/sonsuz dinamik bağlantı tuzaklarına saplanmadan farklı siteleri dengeli keşfetmek', ['Web sayfaları arasındaki köprü bağlantılarının yönsüz graf oluşturması nedeniyle DFS\'nin çalışmaması', 'BFS mimarisinin ziyaret edilen URL adreslerini kaydetmeye hiç ihtiyaç duymaması', 'DFS kullanıldığında HTTP isteklerinin yalnızca alfabetik sırayla gönderilebilmesi'], 'Web grafında takvim veya dinamik parametrelerle sonsuz derinlikte tuzaklar olabilir; BFS tohumlara yakın kaliteli sayfaları dengeli biçimde tarar.'),
  ('Bir DAG üzerinde en uzun yolu (kritik yol) O(V + E) zamanda bulmak için DFS/BFS tabanlı hangi yöntem kullanılır?', 'Topolojik sıralama yapıldıktan sonra düğümler bu sırayla gezilerek maksimum uzaklık gevşetmesi (relaxation) uygulanır', ['Standart BFS kuyruğu kullanılarak her düğüme ilk ulaşılan adım sayısı en uzun yol kabul edilir', 'El sıkışma lemması ile tüm düğüm dereceleri toplanıp ikiye bölünerek kritik yol bulunur', 'Komşuluk matrisinin determinantı hesaplanarak en büyük özdeğer yol uzunluğu olarak seçilir'], 'Genel graflarda en uzun yol NP-zor iken, çevrimsiz yönlü graflarda (DAG) DFS veya Kahn ile topolojik sıra çıkarılıp dinamik programlama gevşetmesiyle O(V + E) sürede kesin çözülür.'),
  ('Topolojik sırası A - B - C - D olan ağırlıklı bir DAG\'da kenarlar A->B(4), A->C(2), B->C(3), B->D(5), C->D(6) ise A\'dan D\'ye en kısa ve en uzun yönlü yol ağırlıkları sırasıyla kaçtır?', 'En kısa 8, en uzun 13', ['En kısa 9, en uzun 11', 'En kısa 7, en uzun 15', 'En kısa 8, en uzun 9'], 'Aday yollar: A-C-D = 2+6 = 8; A-B-D = 4+5 = 9; A-B-C-D = 4+3+6 = 13. Dolayısıyla en kısa yol 8 (A-C-D), en uzun yol 13 (A-B-C-D) olur.'),
  ('Komşuluk matrisi ile temsil edilen V düğümlü yönlü bir grafta "evrensel kuyu" (universal sink: giriş derecesi V-1, çıkış derecesi 0 olan düğüm) bulunup bulunmadığı tam matris taraması O(V²) yerine en iyi hangi karmaşıklıkta saptanabilir?', 'O(V)', ['O(1)', 'O(V log V)', 'O(E²)'], 'A[i][j] == 1 ise i kuyu olamaz, 0 ise j kuyu olamaz; her karşılaştırma bir adayı elediği için V-1 adımda tek aday bulunur ve 2V kontrolle doğrulanarak O(V) zamanda çözülür.'),
  ('Bağlı bileşenleri dinamik olarak kenar eklendikçe sorgulanan bir grafta her sorguda baştan O(V + E) BFS/DFS çalıştırmak yerine neden Ayrık Küme (Union-Find) veri yapısı tercih edilir?', 'Kenar ekleme ve aynı bileşende olma sorgularını neredeyse sabit O(α(V)) zamanda yanıtladığı için', ['Union-Find yapısının ağırlıksız graflarda iki düğüm arasındaki en kısa yolu da otomatik bulması nedeniyle', 'BFS ve DFS algoritmalarının kenar eklendikten sonra yanlış bağlı bileşen sayısı üretmesi yüzünden', 'Union-Find veri yapısının komşuluk matrisiyle O(V³) bellek kullanarak daha güvenli çalışmasından'], 'Yalnızca bağlılık sorgulanıyor ve kenarlar dinamik ekleniyorsa her seferinde O(V+E) gezinti yapmak yerine yol sıkıştırmalı Union-Find kullanmak neredeyse O(1) hız sağlar.'),
  ('Çok yoğun (E yaklaşık V^2 olan) bir grafta Dijkstra algoritması çalıştırılırken ikili yığın yerine basit doğrusal dizi kullanmanın zaman karmaşıklığı açısından etkisi ne olur?', 'O(V^2) karmaşıklık sağlayarak O(V^2 log V) olan ikili yığın kullanımından asimptotik olarak daha hızlı çalışır', ['Zaman karmaşıklığını O(V^3) düzeyine çıkararak algoritmayı yoğun graflarda kullanılmaz hale getirir', 'Bellek kullanımını üstel olarak artırırken çalışma süresinde herhangi bir değişikliğe yol açmaz', 'Negatif ağırlıklı kenarların da doğru biçimde işlenebilmesini sağlayarak algoritmayı genelleştirir'], 'Yoğun grafta E = Theta(V^2) olduğundan dizi ile O(V^2 + E) = O(V^2) elde edilir; ikili yığın ise O(V^2 log V) sürer.'),
  ('Bir harita navigasyon sisteminde tüm kenar ağırlıklarına sabit bir pozitif K sayısı ekleyerek negatif kenarları pozitif yapmak ve ardından Dijkstra çalıştırmak neden doğru en kısa yolu garanti etmez?', 'Daha fazla kenar içeren yollar K sabitini daha çok kez topladığı için az kenarlı yollara göre yapay biçimde cezalandırılır', ['Sabit sayı eklemek grafın yönlü yapısını bozarak tüm kenarları çift yönlü hale getirir', 'Öncelik kuyruğundaki tüm elemanların sırası tamamen tersine döneceği için en uzun yol bulunur', 'Kenar ağırlıklarına sabit eklemek graftaki mevcut tüm çevrimleri negatif ağırlıklı çevrime dönüştürür'], 'k kenarlı bir yolun maliyeti k*K kadar artar; bu durum kenar sayısı farklı iki yol arasındaki maliyet farkını değiştirir.'),
  ('Fibonacci yığını (Fibonacci heap) kullanılan bir Dijkstra uygulamasında zaman karmaşıklığının O(E + V log V) olmasını sağlayan temel veri yapısı özelliği hangisidir?', 'Anahtar azaltma (decrease-key) işleminin amortize O(1) zamanda gerçekleştirilebilmesi', ['Minimum elemanı silme (extract-min) işleminin her durumda sabit O(1) zamanda çalışması', 'Yığındaki tüm elemanların her ekleme sonrasında tam sıralı bir dizide tutulması', 'Kenar gevşetme işlemlerinin yarısının hiç karşılaştırma yapılmadan atlanabilmesi'], 'Fibonacci yığınında extract-min O(log V) iken decrease-key amortize O(1) olduğundan E kez yapılan güncelleme O(E) tutar.'),
  ('Pozitif kenar ağırlıklı bir iletişim ağında her kenarın ağırlığı o hattın "arızalanmama olasılığını" (0 < p <= 1) gösteriyorsa, en güvenilir yolu Dijkstra ile bulmak için kenar ağırlıkları nasıl dönüştürülmelidir?', 'Her p olasılığı -ln(p) değerine dönüştürülerek çarpım maksimizasyonu toplam minimizasyonuna çevrilir', ['Her p olasılığı 1 - p değerine dönüştürülerek doğrudan standart toplama işlemi uygulanır', 'Her p olasılığının karesi alınarak öncelik kuyruğunda en büyük eleman seçilir', 'Her p olasılığı 1 / p değerine dönüştürülüp kenar ağırlıkları birbiriyle toplanır'], 'Olasılıklar çarpılır (p1*p2...); logaritma alıp eksi ile çarpmak (-ln(p) >= 0) çarpımı maksimum yapmayı toplamı minimum yapmaya dönüştürür.'),
  ('Bir döviz piyasasında para birimleri düğümler ve kurlar arası dönüşüm oranları kenarlar olarak modellendiğinde, risksiz arbitraj fırsatı (başladığından daha fazla parayla dönme) Bellman-Ford ile nasıl tespit edilir?', 'Dönüşüm oranlarının R yerine -log(R) ağırlıkları kullanılarak grafta negatif çevrim aranmasıyla', ['Dönüşüm oranlarının doğrudan toplanıp en küçük kapsayan ağacın hesaplanmasıyla', 'Kurlar grafında topolojik sıralama yapılarak en son sıradaki düğümün seçilmesiyle', 'Her para biriminin derecesi sayılıp tek dereceli düğümler arasında Euler yolu aranmasıyla'], 'Çarpımı 1\'den büyük olan R1*R2*...*Rk > 1 çevrimi, -log alındığında toplamı sıfırdan küçük (-log R1 - ... < 0) bir negatif çevrime karşılık gelir.'),
  ('Bellman-Ford algoritmasında herhangi bir turda hiçbir kenar gevşetme işlemi gerçekleşmezse algoritmanın kalan turları beklemeden sonlandırılması (erken çıkış) doğruluğu nasıl etkiler?', 'Doğruluğu hiç bozmadan gereksiz turları önleyerek ortalama çalışma süresini iyileştirir', ['Negatif ağırlıklı kenarların etkisini sıfırladığı için yanlış en kısa yol değerleri üretir', 'Yalnızca yönsüz graflarda doğru çalışır, yönlü graflarda eksik mesafe bırakır', 'Uzak düğümlere giden yolların henüz keşfedilmeden algoritmanın hatalı durmasına yol açar'], 'Bir turda hiçbir d[v] değişmediyse sonraki turlarda da aynı koşullar sınanacağından hiçbir değer değişmeyecektir.'),
  ('Yönsüz ve bağlantılı bir grafta ağırlığı negatif olan tek bir kenar (örneğin u-v kenarı -5) bulunuyorsa Bellman-Ford algoritması bu graf üzerinde nasıl bir sonuç verir?', 'Kenar iki yönde de geçilebildiğinden u-v-u arasında ağırlığı -10 olan negatif çevrim oluştuğunu bildirir', ['Negatif kenarı yalnızca bir kez kullanarak tüm düğümlere ait sonlu en kısa yolları başarıyla bulur', 'Yönsüz graflarda negatif kenar tanımsız olduğu için ilk turda bellek taşması hatası verir', 'Ağırlığı -5 olan kenarı otomatik olarak kapsayan ağacın kök kenarı haline getirir'], 'Yönsüz negatif kenar u -> v (-5) ve v -> u (-5) olarak gidip gelindiğinde her geçişte maliyeti -10 düşüren bir negatif çevrim yaratır.'),
  ('Bir yönlü grafta negatif ağırlıklı bir çevrim bulunmasına rağmen başlangıç düğümü S\'den bu çevrime hiçbir yol yoksa standart S kaynaklı Bellman-Ford algoritması nasıl davranır?', 'S\'den ulaşılabilen düğümlerin uzaklıkları V. turda değişmeyeceği için bu ulaşılmaz negatif çevrimi raporlamaz', ['Graftaki tüm düğümleri istisnasız tarayarak ulaşılmaz negatif çevrimi de ilk turda yakalar', 'S düğümünün başlangıç uzaklığını sıfırdan eksi sonsuza çekerek hatalı sonlanır', 'Ulaşılmaz düğümlere rastgele sonlu ağırlıklar atayarak sonsuz döngüye girer'], 'S\'den ulaşılamayan düğümlerin uzaklığı sonsuz kalır; sonsuz + w < sonsuz sağlanmadığından V. turda gevşeme olmaz.'),
  ('Bağlantısız (örneğin 3 ayrı bağlı bileşenden oluşan) V düğümlü yönsüz bir grafta Kruskal algoritması sonuna kadar çalıştırıldığında ne elde edilir?', 'V - 3 kenardan oluşan bir en küçük kapsayan orman', ['V - 1 kenardan oluşan tek bir bağlantılı en küçük kapsayan ağaç', 'Bileşenler arası kenar olmadığı için çalışma zamanı sonsuz döngü hatası', 'Yalnızca en çok düğüm içeren bileşeni kapsayan tek bir ağaç'], 'k bağlı bileşenli V düğümlü grafta Kruskal her bileşen için ayrı bir MST kurarak toplam V - k kenarlı kapsayan orman üretir.'),
  ('Kapsayan ağaç kuramındaki "kesit özelliği" (cut property) aşağıdakilerden hangisini ifade eder?', 'Düğümleri iki boş olmayan kümeye ayıran herhangi bir kesiti geçen benzersiz en küçük ağırlıklı kenar her MST\'de yer alır', ['Bir graftan en büyük ağırlıklı kenar çıkarıldığında graf her zaman iki eşit parçaya bölünür', 'En küçük kapsayan ağaçtaki en uzun yol her zaman iki yaprak düğüm arasındaki en kısa yoldur', 'Graftaki her çevrimin en küçük ağırlıklı kenarı kapsayan ağaçtan kesinlikle çıkarılmalıdır'], 'Kesit özelliğine göre bir kesiti aşan kenarlar arasında ağırlığı kesin en küçük olan kenar güvenli kenardır ve tüm MST\'lerde bulunur.'),
  ('Kapsayan ağaç kuramındaki "çevrim özelliği" (cycle property) uyarınca, bir çevrimdeki diğer tüm kenarlardan kesinlikle daha büyük ağırlığa sahip olan bir e kenarı için ne söylenebilir?', 'Bu e kenarı grafın hiçbir en küçük kapsayan ağacında yer alamaz', ['Bu e kenarı Kruskal algoritması tarafından ilk sırada seçilmek zorundadır', 'Bu e kenarı silindiğinde grafın bağlantılılık özelliği kesinlikle kaybolur', 'Bu e kenarı yalnızca Prim algoritması tarafından üretilen ağaçlarda bulunur'], 'Çevrimdeki en ağır benzersiz kenar bir MST\'de olsaydı, çıkarılıp çevrimdeki daha hafif kenarla değiştirilerek daha küçük ağırlıklı ağaç elde edilirdi.'),
  ('Bağlantılı bir graftaki tüm kenar ağırlıklarına sabit bir pozitif C sayısı eklendiğinde grafın en küçük kapsayan ağacı (MST) nasıl etkilenir?', 'Ağacı oluşturan kenar kümesi değişmez, yalnızca ağacın toplam maliyeti (V - 1) * C kadar artar', ['Kenar sayısı az olan alt ağaçlar avantaj kazanacağı için MST\'nin yapısı tamamen değişir', 'En küçük kapsayan ağaç en büyük kapsayan ağaca dönüşerek zıt kenarları seçer', 'Sabit ekleme sonrasında Prim algoritmasının ürettiği ağaç V kenarlı hale gelir'], 'Her kapsayan ağaç tam V - 1 kenar içerdiğinden her ağacın maliyeti eşit miktarda ((V-1)*C) artar; sıralama değişmez.'),
  ('Prim algoritması ile Dijkstra algoritmasının öncelik kuyruğu güncelleme adımları karşılaştırıldığında aralarındaki temel fark nedir?', 'Prim düğümün mevcut ağaca olan tek kenar ağırlığını (w), Dijkstra ise kaynağa olan birikimli yol ağırlığını (d[u] + w) anahtar olarak tutar', ['Prim her adımda kuyruktaki en büyük anahtarı çekerken Dijkstra en küçük anahtarı çeker', 'Prim yalnızca yönlü graflarda çalışırken Dijkstra yalnızca yönsüz graflarda çalışır', 'Prim algoritması her düğümü kuyruğa V kez eklerken Dijkstra yalnızca bir kez ekler'], 'Prim ağaca en yakın komşu kenarı arar (key[v] = min w(u,v)), Dijkstra ise başlangıç noktasına en yakın toplam yolu arar (d[v] = min d[u]+w(u,v)).'),
  ('Bağlantılı, yönsüz ve ağırlıklı bir grafta "en büyük kapsayan ağaç" (toplam kenar ağırlığı maksimum olan ağaç) Kruskal algoritmasıyla nasıl bulunabilir?', 'Kenarlar ağırlıklarına göre büyükten küçüğe sıralanıp çevrim oluşturmayanlar sırayla seçilerek', ['Kenar ağırlıklarının kareleri alınıp standart küçükten büyüğe Kruskal çalıştırılarak', 'Union-Find veri yapısı yerine ilk giren ilk çıkar kuyruk (Queue) kullanılarak', 'Yalnızca yaprak düğümler arasındaki kenarlar seçilip iç kenarlar silinerek'], 'Kenarları azalan sırada dizmek (veya tüm ağırlıkları -1 ile çarpıp standart MST bulmak) maksimum toplam ağırlıklı kapsayan ağacı verir.'),
  ('Union-Find veri yapısında "yol sıkıştırma" (path compression) ve "dereceye göre birleştirme" (union by rank) iyileştirmeleri birlikte kullanıldığında m işlemlik bir dizinin zaman karmaşıklığı ne olur?', 'O(m * alpha(V))', ['O(m * V)', 'O(m * log^2 V)', 'O(m * V log V)'], 'İki iyileştirme bir arada kullanıldığında işlem başına amortize maliyet ters Ackermann fonksiyonu O(alpha(V)) olur.'),
  ('Kenar ağırlıkları pozitif olan bağlantılı bir grafta "darboğaz kapsayan ağaç" (en ağır kenarının ağırlığı mümkün olan en küçük değerde olan ağaç) ile MST arasındaki ilişki nedir?', 'Her en küçük kapsayan ağaç (MST) aynı zamanda bir darboğaz kapsayan ağaçtır, ancak tersi her zaman doğru değildir', ['Hiçbir en küçük kapsayan ağaç aynı zamanda darboğaz kapsayan ağaç olamaz', 'Yalnızca tüm kenar ağırlıkları eşit olduğunda iki ağaç türü aynı maksimum kenar değerini verir', 'Darboğaz kapsayan ağaç her zaman V + 1 kenar içerdiği için MST\'den farklıdır'], 'Kruskal en küçük kenarları sırayla eklediği için ağacı bağlayan son zorunlu eşik kenarını minimize eder; dolayısıyla her MST aynı zamanda darboğaz ağacıdır.'),
  ('İkinci en küçük kapsayan ağacı (toplam ağırlığı MST\'den büyük veya eşit olan, kenar kümesi farklı en ucuz ağaç) bulmak için hangi yöntem kesin sonuç verir?', 'MST dışındaki her u-v kenarı için, MST\'deki u-v yolunun en ağır kenarını çıkarıp u-v\'yi ekleyerek oluşan ağaçlardan en küçüğünü seçmek', ['Kruskal algoritmasında en küçük kenarı en başta silip kalan graf üzerinde tek bir kez MST çalıştırmak', 'Prim algoritmasını en yüksek dereceli düğüm yerine en düşük dereceli düğümden başlatmak', 'MST içerisindeki en hafif ve en ağır iki kenarı aynı anda silip rastgele iki kenar eklemek'], 'İkinci en iyi kapsayan ağaç, bir MST\'den tek bir kenar değişimi (bir ağaç dışı kenar ekleme ve oluşan çevrimdeki en ağır ağaç kenarını çıkarma) uzaklığındadır.'),
  ('Bir şehir ağında sadece kenarların değil düğümlerin de pozitif geçiş ücreti (maliyet[v]) varsa, standart Dijkstra ile en ucuz yolu bulmak için graf nasıl modellenebilir?', 'Her u -> v kenarının yeni ağırlığı w(u,v) + maliyet[v] yapılarak', ['Düğüm maliyetleri kenar ağırlıklarından çıkarılıp oluşan negatif sayılarla Dijkstra çalıştırılarak', 'Graftaki tüm kenar yönleri ters çevrilip düğüm maliyetleri sıfır kabul edilerek', 'Her düğümün geçiş ücreti yalnızca o düğümden çıkan en uzun kenara eklenerek'], 'v düğümüne her girişte maliyet[v] ödendiğinden bu ücreti v\'ye giren kenarların ağırlığına eklemek problemi standart kenar ağırlıklı en kısa yola indirger.'),
  ('Ağırlıkları pozitif olan yönlü veya yönsüz bir grafta tek kaynaktan hesaplanan tüm onceki[v] bağlantılarının oluşturduğu "en kısa yol ağacı" (SPT) hangi yapısal özelliği taşır?', 'Kaynağa ulaşılabilen düğümleri kapsayan, kökü kaynak düğüm olan ve çevrim içermeyen bir ağaçtır', ['Her zaman grafın en küçük kapsayan ağacı (MST) ile aynı toplam kenar ağırlığına sahiptir', 'Graftaki kenarların tamamını istisnasız içeren bir Euler alt grafıdır', 'Her düğümün çıkış derecesinin tam olarak iki olduğu dengeli bir ikili ağaçtır'], 'Pozitif ağırlıklarda en kısa yollar çevrim içermez; ulaşılabilir k düğüm için k - 1 kenarlı köklü bir ağaç oluşur.'),
  ('Hedef düğümün belirli olduğu büyük bir yol ağında "çift yönlü (bidirectional) Dijkstra" çalıştırmanın standart tek yönlü Dijkstra\'ya göre temel performans avantajı nedir?', 'Kaynak ve hedeften eşzamanlı genişleyen iki küçük arama dairesinin kesişmesiyle taranan düğüm sayısını önemli ölçüde azaltması', ['Negatif ağırlıklı kenarları ve negatif çevrimleri ek maliyet olmadan düzeltmesi', 'En kötü durum teorik zaman karmaşıklığını O(1) sabit zamana indirmesi', 'Öncelik kuyruğu ihtiyacını tamamen ortadan kaldırarak yalnızca yığın bellekle çalışması'], 'Yarıçapı R olan tek bir büyük arama alanı yerine yarıçapı R/2 olan iki arama alanı genişletilerek pratikte çok daha az düğüm incelenir.'),
  ('Negatif kenarlar içeren ancak negatif çevrim barındırmayan seyrek bir yönlü grafta tüm düğüm çiftleri arası en kısa yolları bulmak için Johnson algoritması Bellman-Ford ve Dijkstra\'yı nasıl birleştirir?', 'Bellman-Ford ile bir kez düğüm potansiyelleri hesaplayıp kenar ağırlıklarını negatif olmayacak şekilde yeniden ağırlıklandırır, sonra her düğümden Dijkstra çalıştırır', ['Önce her düğümden Dijkstra çalıştırıp hatalı çıkan düğümler için Bellman-Ford algoritmasını tekrarlar', 'Negatif kenarları silip Dijkstra çalıştırdıktan sonra silinen kenarları Bellman-Ford ile sonuca ekler', 'Grafı yönsüz hale getirip Kruskal ile ağaç kurduktan sonra ağaç üzerinde Bellman-Ford uygular'], 'Johnson algoritması h(u) - h(v) potansiyel farkıyla w\'(u,v) = w(u,v) + h(u) - h(v) >= 0 dönüşümü yapar; en kısa yollar korunur ve V kez hızlı Dijkstra çalışır.'),
  ('Bir veri merkezinde 6 sunucuyu birbirine bağlayacak ağ tasarımında, sunuculardan ikisi (S1 ve S2) arasına halihazırda ücretsiz bir fiber hat çekilmiştir. Kalan bağlantıları en ucuza tamamlamak için MST algoritması nasıl uyarlanır?', 'S1-S2 kenarının ağırlığı 0 kabul edilerek (veya Union-Find\'da S1 ve S2 baştan birleştirilerek) standart Kruskal çalıştırılır', ['S1 ve S2 düğümleri graftan tamamen silinip kalan 4 sunucu için MST bulunur', 'S1 ve S2 arasındaki kenara sonsuz ağırlık verilerek diğer tüm yolların bu hattan kaçınması sağlanır', 'Yalnızca S1 düğümünden çıkan kenarlar kullanılarak yıldız topolojisi oluşturulur'], 'Mevcut ücretsiz hat S1 ve S2\'yi 0 maliyetle aynı bileşene koyar; Union(S1, S2) sonrası standart Kruskal en ucuz tamamlamayı bulur.'),
  ('Her bağlı bileşenin kendi dışına çıkan en küçük ağırlıklı kenarını eşzamanlı olarak seçip bileşenleri birleştirerek O(E log V) zamanda MST bulan ve paralel hesaplamaya çok uygun olan algoritma hangisidir?', 'Boruvka algoritması', ['Bellman-Ford algoritması', 'Dijkstra algoritması', 'Floyd-Warshall algoritması'], 'Boruvka algoritması her aşamada tüm bileşenlerin en ucuz dış kenarlarını paralel seçer; bileşen sayısı her turda en az yarıya iner.'),
  ('Bir SPFA (kuyruk tabanlı Bellman-Ford) uygulamasında V düğümlü bir grafta negatif ağırlıklı ulaşılabilir bir çevrim olduğu nasıl anlaşılır?', 'Herhangi bir düğümün kenar gevşetme yoluyla kuyruğa eklenme veya güncellenme sayısının V değerine ulaşmasıyla', ['Kuyruğun ilk adımdan hemen sonra tamamen boşalmasıyla', 'Başlangıç düğümünün çıkış derecesinin giriş derecesinden büyük çıkmasıyla', 'Toplam kenar sayısının düğüm sayısından fazla olduğunun görülmesiyle'], 'Çevrimsiz en kısa yol en fazla V - 1 kenar içerir; bir düğüm V kez iyileştiriliyorsa negatif çevrim etkisi altındadır.'),
  ('Farklı kümeleme (clustering) uygulamalarında N veri noktasını birbirine en uzak (maksimum ayırma mesafeli) k kümeye ayırmak için Kruskal algoritması nasıl kullanılır?', 'Nokta çiftleri arası uzaklıklarla Kruskal çalıştırılıp en son eklenecek (k - 1) adet en uzun kenar eklenmeden algoritma durdurulur', ['Kruskal algoritması yalnızca ilk k kenarı ekleyene kadar çalıştırılıp hemen durdurulur', 'Uzaklıklar büyükten küçüğe sıralanıp ilk (N - 1) kenarın tamamı seçilir', 'Yalnızca tek numaralı veri noktaları arasında en küçük kapsayan ağaç kurulur'], 'Tek bağlantılı (single-linkage) k-kümelemede Kruskal N - k kenar eklediğinde tam k ayrık bileşen kalır ve kümeler arası minimum mesafe maksimize edilir.'),
  ('Ağırlıklı yönsüz bir grafta bazı kenarların ağırlıkları birbirine eşitse farklı MST\'ler oluşabilir. Bu durumda tüm olası en küçük kapsayan ağaçların ortak özelliği aşağıdakilerden hangisidir?', 'Her bir MST içerisinde belirli bir w ağırlığına sahip kenarların sayısı tüm MST\'lerde birbirine eşittir', ['Tüm MST\'lerin yaprak düğüm sayıları her zaman birbirine eşittir', 'Tüm MST\'lerin çapı (en uzak iki düğüm arası mesafe) her zaman birbirine eşittir', 'Eşit ağırlıklı kenarların hiçbiri herhangi bir MST içerisine dahil edilemez'], 'MST ağırlık dağılımı teoremine göre bir grafın tüm farklı en küçük kapsayan ağaçları her bir kenar ağırlığından tam olarak eşit adette içerir.'),
  ('Sonlu ve boş olmayan her yönlü çevrimsiz grafta (DAG) giriş derecesi 0 olan en az bir kaynak düğüm ve çıkış derecesi 0 olan en az bir batak (sink) düğüm bulunmasının nedeni nedir?', 'Öyle olmasaydı her düğümden ileri veya geri gidilerek sonlu sayıda adımda mutlaka bir düğüm tekrarlanır ve çevrim oluşurdu', ['DAG yapılarında kenar sayısı her zaman düğüm sayısının tam yarısına eşit olmak zorundadır', 'Topolojik sıralama algoritmaları çalışmaya başlamadan önce bu iki düğümü grafiğe yapay olarak ekler', 'Yönlü graflarda tüm düğümlerin giriş dereceleri toplamı her zaman sıfıra eşittir'], 'Çıkış derecesi 0 olan düğüm bulunmasaydı sonsuza dek ilerlenebilirdi; sonlu V düğümde güvercin yuvası ilkesiyle bir düğüm tekrar edilip çevrim yaratırdı.'),
  ('Genel graflarda NP-zor olan "en uzun basit yol" (longest path) problemi, bir DAG üzerinde proje yönetimindeki "kritik yol" (CPM) hesabında nasıl O(V + E) zamanda çözülür?', 'Topolojik sıra boyunca d[v] = max(d[v], d[u] + w(u,v)) güncellemesi yapılarak', ['Kruskal algoritmasında kenarlar büyükten küçüğe sıralanıp kapsayan ağaç kurularak', 'Graftaki tüm kenar yönleri silinip standart genişlik öncelikli arama çalıştırılarak', 'Her düğüm çifti arasında Euler turu aranıp kenar sayıları toplanarak'], 'Çevrim bulunmadığı için en uzun yol alt yapı özelliğini korur ve topolojik sıra üzerinde dinamik programlamayla doğrusal sürede hesaplanır.'),
  ('V düğümlü bir DAG\'da olası maksimum yönlü kenar sayısı kaçtır ve bu sınıra hangi durumda ulaşılır?', 'V * (V - 1) / 2 kenardır; topolojik sıradaki her düğümden kendisinden sonra gelen tüm düğümlere yönlü kenar çizildiğinde ulaşılır', ['V - 1 kenardır; graf tek bir doğrusal zincir haline geldiğinde ulaşılır', 'V^2 kenardır; her düğümden kendisine ve diğer tüm düğümlere kenar çizildiğinde ulaşılır', '2V - 2 kenardır; graf düzlemsel bir üçgenleme yapısına kavuştuğunda ulaşılır'], 'Topolojik sıraya göre yalnızca i < j iken u_i -> u_j kenarı eklenebilir; bu da tam olarak V\'nin 2\'li kombinasyonu kadar kenar verir ve çevrim oluşturmaz.'),
  ('Bir DAG üzerinde S düğümünden T düğümüne giden "farklı yönlü yolların toplam sayısını" O(V + E) zamanda hesaplayan dinamik programlama bağıntısı nasıl çalışır?', 'yol[S] = 1 atanır ve topolojik sırayla her u düğümü için komşusu v\'ye yol[v] += yol[u] eklemesi yapılır', ['Her kenara 1 ağırlığı verilip Dijkstra çalıştırılarak T\'nin uzaklığı okunur', 'S ve T arasındaki kenar kesiti bulunup kesitteki kenar sayısı ikiyle çarpılır', 'DFS ile tüm yollar tek tek ekrana yazdırılıp üstel zamanda sayılır'], 'DAG\'da çevrim olmadığından u üzerinden v\'ye gelen farklı yollar topolojik sırada ayrık biçimde toplanarak O(V + E) sürede tam sayıyı verir.'),
  ('Yönsüz bir graftaki her kenara çevrim oluşturmayacak şekilde bir yön vererek grafı bir DAG haline getirme işlemine (acyclic orientation) ilişkin aşağıdakilerden hangisi her zaman doğrudur?', 'Basit (öz-ilmek içermeyen) her yönsüz graf, düğümlerine 1\'den V\'ye numara verilip kenarlar küçük numaradan büyüğe yönlendirilerek bir DAG\'a dönüştürülebilir', ['Yalnızca ağaç yapısındaki yönsüz graflara çevrimsiz yönlendirme yapılabilir; çevrimli yönsüz graflar her zaman yönlü çevrim üretir', 'Tek sayıda düğüm içeren tam grafların hiçbir çevrimsiz yönlendirmesi bulunamaz', 'Yönsüz bir grafı DAG yapmak için kenarlarının en az yarısının silinmesi zorunludur'], 'Düğümlere keyfi bir sıralama verip tüm kenarları küçük indisten büyük indise yönlendirmek geri dönüşü imkansız kılar ve kesinlikle bir DAG üretir.'),
  ('Keyfi bir yönlü grafın güçlü bağlantılı bileşenleri (SCC - Strongly Connected Components) Kosaraju veya Tarjan algoritmasıyla bulunup her bileşen tek bir süper düğüme büzüştürüldüğünde (condensation graph) ortaya çıkan yeni grafın yapısı nedir?', 'Her zaman yönlü çevrimsiz bir graftır', ['Her zaman çift parçalı (bipartite) yönsüz bir ağaçtır', 'Her zaman tek bir Euler çevrimi içeren tam graftır', 'Her zaman negatif ağırlıklı çevrimler içeren yönlü bir halkadır'], 'İki farklı SCC arasında karşılıklı yönlü yol olsaydı ikisi tek bir SCC olurdu; dolayısıyla bileşenler üst grafı kesinlikle bir DAG\'dır.'),
  ('Yönlü ve zayıf bağlantılı bir grafta kapalı çevrim olmayan açık bir "yönlü Euler yolu" bulunması için derece koşulu nedir?', 'Bir düğümde çıkış - giriş = 1 (başlangıç), bir düğümde giriş - çıkış = 1 (bitiş) ve diğer tüm düğümlerde giriş = çıkış olmalıdır', ['İki düğümde çıkış - giriş = 2 ve diğer tüm düğümlerde giriş derecesi sıfır olmalıdır', 'Tüm düğümlerde giriş derecesi ile çıkış derecesinin toplamı tek sayı olmalıdır', 'Başlangıç ve bitiş düğümlerinin her ikisinde de giriş derecesi sıfır olmalıdır'], 'Yolun başladığı düğümden bir kez fazladan çıkılır (out - in = 1), bittiği düğüme bir kez fazladan girilir (in - out = 1), ara düğümlerde giriş ve çıkış dengelenir.'),
  ('Euler yolu bulmak için kullanılan "Fleury algoritmasında" mevcut düğümden çıkarken birden fazla kenar seçeneği varsa uyulması gereken temel kural nedir?', 'Başka bir seçenek olduğu sürece kalan grafı ikiye bölen bir "köprü" (bridge / cut-edge) kenarı üzerinden geçilmemelidir', ['Her adımda numarası en büyük olan komşu düğüme giden kenar seçilmelidir', 'Her adımda daha önce en çok ziyaret edilmiş düğüme giden kenar seçilmelidir', 'Yalnızca üçgen oluşturan kenarlar seçilip diğer kenarlar sona bırakılmalıdır'], 'Köprü kenarından erken geçmek grafın geride kalan kenarlarına geri dönüşü imkansız kılar; bu yüzden Fleury mecbur kalmadıkça köprülerden kaçınır.'),
  ('Biyoinformatikte kısa DNA okumalarından (k-mer) tam genom dizisini birleştirmek (genome assembly) için Hamilton yolu yerine "De Bruijn grafında Euler yolu" yaklaşımının tercih edilmesinin temel hesaplama nedeni nedir?', 'Hamilton yolu bulmak NP-tam (zor) iken De Bruijn grafında her k-mer\'i kenar yaparak Euler yolu bulmak O(E) doğrusal zamanda çözülür', ['Euler yolu her zaman genomdaki mutasyonları otomatik olarak silip temizler', 'Hamilton yolu yalnızca çift uzunluktaki DNA dizilerinde tanımlanabilir', 'De Bruijn grafları hiçbir zaman çevrim içermez ve topolojik sıralamayla çözülür'], 'Milyonlarca okuma için NP-tam Hamilton yolu hesaplanamazken, (k-1)-mer düğümler arası k-mer kenarlarla kurulan De Bruijn grafında Euler yolu doğrusal sürede bulunur.'),
  ('V >= 3 düğümlü basit yönsüz bir grafta "Dirac Teoremi" uyarınca bir Hamilton çevriminin varlığını garanti eden yeterli (ancak zorunlu olmayan) derece koşulu nedir?', 'Graftaki her bir düğümün derecesinin en az V / 2 olması', ['Graftaki her bir düğümün derecesinin çift sayı olması', 'Graftaki toplam kenar sayısının en az V - 1 olması', 'Grafta derecesi 2 olan en az bir düğümün bulunması'], 'Dirac teoremine göre V >= 3 için her v düğümünde deg(v) >= V/2 ise grafta mutlaka Hamilton çevrimi vardır (tersi şart değildir, örneğin C6 halkasında dereceler 2\'dir ama Hamilton çevrimi vardır).'),
  ('İki parçalı (bipartite) yönsüz bir G = (A, B, E) grafında A kümesinde 6 düğüm ve B kümesinde 8 düğüm bulunuyorsa (kenarlar yalnızca A ile B arasındaysa) bu grafta Hamilton çevrimi veya Hamilton yolu bulunabilir mi?', 'Ne Hamilton çevrimi ne de Hamilton yolu bulunabilir; çünkü yol A ve B arasında sırayla zıplamak zorundadır ve |A| ile |B| farkı 1\'den büyüktür', ['Hem Hamilton çevrimi hem de Hamilton yolu bulunabilir; yeter ki tüm düğüm dereceleri çift olsun', 'Hamilton çevrimi bulunamaz ancak B kümesinden başlayıp B kümesinde biten bir Hamilton yolu bulunabilir', 'Yalnızca A kümesindeki düğümler kendi aralarında sıralanırsa Hamilton çevrimi elde edilir'], 'İki parçalı grafta her adımda küme değişir (A-B-A-B...); Hamilton çevrimi için |A| = |B| olmalı, Hamilton yolu için ise ||A| - |B|| <= 1 olmalıdır (8 - 6 = 2 olduğundan ikisi de imkansızdır).'),
  ('V düğümlü bir grafta Bitmask Dinamik Programlama (Held-Karp algoritması) kullanılarak Hamilton yolu / Gezgin Satıcı Problemi çözüldüğünde kaba kuvvet O(V!) yerine hangi zaman karmaşıklığına inilir?', 'O(V^2 * 2^V)', ['O(V * log V)', 'O(V^3)', 'O(E + V)'], 'dp[mask][u] durumu "ziyaret edilen düğüm alt kümesi (2^V durum) ve son bulunulan u düğümü (V durum)" olarak tanımlanıp V geçişle O(V^2 * 2^V) sürede çözülür.'),
  ('Bir grafta derecesi 1 olan (sarkık / yaprak) 3 farklı düğüm bulunuyorsa bu grafta Euler yolu, Euler çevrimi, Hamilton yolu ve Hamilton çevrimi varlığı hakkında ne söylenebilir?', 'Dördü de kesinlikle bulunamaz', ['Euler yolu bulunabilir ancak diğer üçü bulunamaz', 'Hamilton yolu bulunabilir ancak diğer üçü bulunamaz', 'Yalnızca Euler çevrimi ve Hamilton yolu bulunabilir'], '3 tek dereceli düğüm olduğu için Euler çevrimi (0 tek ister) ve Euler yolu (2 tek ister) olamaz; derecesi 1 olan düğüm bir yolun yalnızca uç noktası olabileceğinden ve bir yolun en fazla 2 ucu olduğundan 3 yapraklı grafta Hamilton yolu/çevrimi de olamaz!'),
  ('n boyutlu hiperküp grafı Qn\'de (2^n düğüm, her düğüm n bitlik ikili dizge, komşular yalnız 1 bitte farklı) bir Hamilton çevrimi bulunması sayısal elektronikteki hangi kodlama yapısına birebir karşılık gelir?', 'Ardışık terimleri yalnızca 1 bit değişen döngüsel n-bit Gray koduna', ['Hata düzelten Hamming kontrol biti matrisine', 'Değişken uzunluklu Huffman önek sıkıştırma ağacına', 'İkinin tümleyeni işaretli tam sayı aritmetiğine'], 'Qn grafında komşu düğümler tam 1 bitte farklılaşır; tüm 2^n düğümü birer kez gezip başa dönen Hamilton çevrimi doğrudan n-bitlik döngüsel Gray kodudur.'),
  ('Yönlü çevrimsiz bir görev grafında (DAG) tüm görevler tam 1 saat sürüyorsa ve DAG içindeki en uzun düğüm zinciri k adet düğüm içeriyorsa, tüm görevleri çakışmadan zaman dilimlerine (katmanlara) atamak için en az kaç saat gerekir?', 'Tam olarak k saat gerekir', ['k * (k - 1) / 2 saat gerekir', '2^k saat gerekir', 'V - k saat gerekir'], 'Birim süreli görevlerde paralel yürütme katmanlarının sayısı, DAG üzerindeki maksimum zincir uzunluğu olan k sayısına eşittir.'),
  ('Bir DAG üzerinde topolojik sıralama yapıldıktan sonra, u düğümü listede v düğümünden daha önce (solda) yer alıyorsa u ile v arasındaki ulaşılabilirlik hakkında ne söylenebilir?', 'v düğümünden u düğümüne giden yönlü bir yol kesinlikle yoktur; ancak u\'dan v\'ye yol olabilir de olmayabilir de', ['u düğümünden v düğümüne her zaman doğrudan veya dolaylı yönlü bir yol vardır', 'u ve v düğümleri kesinlikle aynı güçlü bağlantılı bileşen içerisindedir', 'u düğümünün çıkış derecesi her zaman v düğümünün çıkış derecesinden büyüktür'], 'Topolojik sıra v -> ... -> u geri yolunu yasaklar; fakat u\'nun v\'den önce gelmesi aralarında bağımlılık olduğu anlamına gelmez (bağımsız iki dal da olabilir).'),
  ('V düğümlü basit yönsüz bir grafta "Ore Teoremi" uyarınca bir Hamilton çevriminin varlığını garanti eden koşul aşağıdakilerden hangisidir?', 'Birbirine doğrudan komşu olmayan her u ve v düğüm çifti için deg(u) + deg(v) >= V eşitsizliğinin sağlanması', ['Birbirine doğrudan komşu olan her u ve v düğüm çifti için deg(u) * deg(v) >= V^2 olması', 'Graftaki en küçük dereceli düğümle en büyük dereceli düğümün toplamının çift sayı olması', 'Graftaki kenar sayısının düğüm sayısının iki katından az olması'], 'Ore teoremi Dirac koşulunu genelleştirir: V >= 3 için komşu olmayan her u, v çiftinde dereceler toplamı en az V ise Hamilton çevrimi kesindir.'),
  ('Her etkinliğin farklı bir kâr (ağırlık) değerine sahip olduğu "ağırlıklı etkinlik seçimi" probleminde klasik erken bitiş zamanlı açgözlü algoritma neden yetersiz kalır?', 'Erken biten düşük değerli bir etkinlik, çok yüksek değerli uzun bir etkinliği dışlayabileceği için', ['Ağırlıklı etkinliklerde bitiş zamanlarının sıralanması matematiksel olarak imkânsız olduğu için', 'Ağırlıklar negatif olmasa bile alt problemler optimal alt yapı özelliğini tamamen kaybettiği için', 'Etkinlik sayısı arttıkça ağırlıkların toplamı tamsayı sınırlarını her durumda aştığı için'], 'Ağırlıklar işin içine girdiğinde sayı maksimizasyonu yerine toplam değer maksimizasyonu gerekir ve bu durum dinamik programlama gerektirir.'),
  ('Çanta kapasitesi 50 kg ve eşyalar A(değer:60, ağırlık:10), B(değer:100, ağırlık:20), C(değer:120, ağırlık:30) iken 0-1 sırt çantasında açgözlü yaklaşım ile optimal çözüm arasındaki fark kaçtır?', '60', ['0', '20', '40'], 'Birim değere göre açgözlü seçim A ve B\'yi alır (30 kg, 160 değer, kalan 20 kg boş kalır); oysa B ve C birlikte 50 kg eder ve 220 değer verir (220 - 160 = 60).'),
  ('0-1 sırt çantası probleminin O(n · W) olan dinamik programlama zaman karmaşıklığı neden "sözde polinom zamanlı" (pseudo-polynomial) olarak sınıflandırılır?', 'Çalışma süresi W değerinin kendisine bağlı olup W\'yi ifade eden bit sayısına göre üstel büyüdüğü için', ['Algoritma yalnızca kayan noktalı (floating-point) ağırlık değerleri üzerinde yaklaşık sonuç ürettiği için', 'Tablolama sırasında kullanılan yardımcı bellek miktarı eşya sayısının faktöriyeliyle orantılı olduğu için', 'En kötü durumda algoritmanın geri izleme (backtracking) aşaması sonsuz döngüye girebildiği için'], 'Girdi boyutu W\'nin bit uzunluğu olan log₂(W) ile ölçülür; W = 2ᵏ olduğunda O(n · 2ᵏ) gerçekte girdi boyutuna göre üsteldir.'),
  ('Madeni para birimleri {1, 15, 25} olan bir sistemde açgözlü algoritmanın optimal çözümü bulamadığı en küçük pozitif tam sayı tutarı kaçtır?', '30', ['20', '40', '45'], '30 için açgözlü algoritma 25 + 1+1+1+1+1 (6 para) seçerken optimal çözüm 15 + 15 (2 para) şeklindedir; daha küçük hiçbir tutarda yanılmaz.'),
  ('Yönlü bir çizgede çevrim içermeyen "en kısa yol" problemi optimal alt yapıya sahipken, "en uzun basit yol" (tekrarsız düğümlü) problemi neden optimal alt yapıya sahip değildir?', 'Alt yolların optimal çözümleri birleştirildiğinde ortak düğümler tekrar edilerek basit yol kuralı bozulabildiği için', ['En uzun yol probleminde kenar ağırlıklarının toplamı her zaman sıfıra eşit çıktığı için', 'Çizgedeki düğüm sayısı çift olduğunda en uzun yolun hesaplanması tanımsız kaldığı için', 'En kısa yol algoritmaları yalnızca ağaç yapılarında çalışıp genel çizgelerde çalışmadığı için'], 'A\'dan C\'ye en uzun basit yol A-B-C iken A-B ve B-C ayrı ayrı en uzun basit yolları seçtiğinde aynı düğümü iki kez kullanıp kuralı ihlal edebilir.'),
  ('Sırasıyla n elemanlı bir dizide yalnızca önceki iki duruma (dp[i-1] ve dp[i-2]) bağımlı olan bir tablolama algoritmasında bellek karmaşıklığı O(n)\'den O(1)\'e nasıl düşürülür?', 'Tüm diziyi saklamak yerine yalnızca son iki durumu tutan iki değişkeni kaydırarak güncelleyerek', ['Dizinin elemanlarını ikili arama ağacına dönüştürüp kök düğümde toplayarak', 'Özyineleme derinliğini iki katına çıkarıp tüm yerel değişkenleri global belleğe taşıyarak', 'Tablodaki çift indisli elemanları silip yalnızca asal indisli elemanları tutarak'], 'Yalnızca son iki değer gerekiyorsa onceki1 ve onceki2 gibi iki skaler değişken yeterlidir; böylece ek dizi belleği O(1) olur.'),
  ('LCS probleminde yalnızca uzunluğu değil, ortak alt dizinin kendisini de (karakterlerini) geri izleme (backtracking) ile bulmak istediğimizde tek satırlık O(min(m, n)) bellek optimizasyonu neden doğrudan yeterli olmaz?', 'Önceki satırların karar geçmişi üzerine yazıldığı için geri izleme yolu kaybolduğundan', ['Tek satırlık dizide sayısal uzunluk değeri bile yanlış hesaplandığından', 'Karakter dizgileri yalnızca iki boyutlu matrislerde ASCII koduna çevrilebildiğinden', 'Bellek optimizasyonu yapıldığında zaman karmaşıklığı üstel düzeye çıktığından'], 'Yalnızca son iki satırı tutmak uzunluğu doğru verir ancak başlangıca doğru çapraz/yukarı/sol adımları izlemek için ya tam tablo ya da Hirschberg algoritması gerekir.'),
  ('Yalnızca karakter "ekleme" ve "silme" işlemlerine izin verilen (değiştirme işlemine izin verilmeyen) düzenleme mesafesi d(X, Y) ile en uzun ortak alt dizi LCS(X, Y) arasında hangi kesin matematiksel ilişki vardır?', 'd(X, Y) = |X| + |Y| - 2 · LCS(X, Y)', ['d(X, Y) = |X| · |Y| - LCS(X, Y)', 'd(X, Y) = max(|X|, |Y|) - LCS(X, Y)', 'd(X, Y) = |X| + |Y| - LCS(X, Y)'], 'Ortak alt dizideki LCS(X, Y) karakter korunur; X\'ten kalan |X| - LCS karakter silinir ve Y\'deki eksik |Y| - LCS karakter eklenir, toplam |X| + |Y| - 2·LCS olur.'),
  ('Etkinlik seçimi probleminde "en erken başlayanı seç" yerine "en geç başlayanı seç" şeklinde sondan başa doğru çalışan bir açgözlü algoritma optimal sonucu verir mi?', 'Evet, zaman eksenindeki simetri nedeniyle en geç başlayan etkinlik geriye kalan başlangıç aralığını maksimize eder', ['Hayır, sondan başa doğru gidildiğinde çakışan etkinliklerin sayısı her zaman iki katına çıkar', 'Hayır, açgözlü algoritmalar yalnızca zamanın ileri aktığı yönlerde matematiksel olarak geçerlidir', 'Yalnızca tüm etkinliklerin süreleri birbirine tam olarak eşit olduğunda doğru sonucu verir'], 'En geç başlayan etkinliği seçmek, ondan önce bitecek etkinlikler için maksimum [0, başlangıç] zaman penceresini bırakır; erken bitiş seçiminin tam simetriğidir.'),
  ('Eşyaların tüm ağırlıklarının birbirine eşit (örneğin hepsi w kg) olduğu özel bir 0-1 sırt çantası probleminde açgözlü algoritma optimal sonucu bulabilir mi?', 'Evet, en yüksek değerli eşyalardan başlayarak kapasite yettiği kadar seçmek her zaman optimaldir', ['Hayır, 0-1 sırt çantası her durumda NP-zor olduğu için eşit ağırlıkta bile açgözlü yaklaşım yanılır', 'Yalnızca çanta kapasitesi eşya ağırlığının tam katı olmadığında optimal sonucu bulabilir', 'Hayır, eşit ağırlıklı eşyalarda birim değer oranları tanımsız hale geldiği için sıralama yapılamaz'], 'Tüm eşyalar aynı w ağırlığındaysa çantaya en fazla ⌊W/w⌋ adet eşya sığar; değeri en büyük olan ilk ⌊W/w⌋ eşyayı seçmek kesinlikle optimaldir.'),
  ('Durum uzayı çok büyük ancak erişilen geçerli durum sayısı çok az (seyrek) olan bir dinamik programlama probleminde dizi yerine karma tablo (hash map) ile memoization kullanmanın temel katkısı nedir?', 'Tüm olası durumlar için devasa bir dizi ayırmak yerine yalnızca ziyaret edilen durumlar kadar bellek harcaması', ['Karma tablo erişimlerinin her zaman sabit dizilerden daha düşük sabit çarpanlı olması', 'Alt problemlerin örtüşme sayısını sıfıra indirerek problemi böl ve yönet yapısına çevirmesi', 'Taban durumların tanımlanmasına gerek kalmadan algoritmanın kendi kendine durmasını sağlaması'], 'Örneğin indisler 10⁹\'a kadar çıkıyor ama yalnızca birkaç bin duruma uğranıyorsa, dizi belleğe sığmazken hash tablosu yalnızca uğranan durumları saklar.'),
  ('Bir X dizgisi ile kendisinin ters çevrilmiş hali olan ters(X) dizgisinin en uzun ortak alt dizisini (LCS(X, ters(X))) bulmak, X içindeki hangi yapının uzunluğunu verir?', 'En uzun palindromik alt dizinin uzunluğunu', ['En uzun tekrarsız karakter alt dizgisinin uzunluğunu', 'Dizgideki farklı harf çeşitlerinin toplam sayısını', 'Dizgiyi sıralamak için gereken minimum takas sayısını'], 'Hem baştan sona (X) hem sondan başa (ters(X)) aynı sırayla okunabilen en uzun alt dizi, tanım gereği en uzun palindromik alt dizidir.'),
  ('Düzenleme mesafesi probleminde "ekleme: 1, silme: 1, değiştirme: 3" şeklinde işlem maliyetleri ağırlıklandırılırsa algoritmada optimal sonuç için değiştirme işlemi ne zaman tercih edilir?', 'Hiçbir zaman; çünkü 1 silme + 1 ekleme toplam 2 maliyetle 3 maliyetli değiştirmeden her zaman daha ucuzdur', ['Yalnızca dizgilerin uzunlukları birbirine tam olarak eşit olduğunda tercih edilir', 'Yalnızca ilk ve son karakterler birbirinden farklı olduğunda tercih edilir', 'Her zaman; çünkü çapraz geçiş tablodaki adım sayısını yarıya indirir'], 'Bir karakteri silip (1) yerine yenisini eklemek (1) toplam 2 birim tutar; değiştirme maliyeti 3 olduğunda algoritma çapraz değiştirme yerine sil+ekle yolunu seçer.'),
  ('Birbiriyle çakışan etkinliklerin hiçbirini iptal etmeden tüm etkinlikleri gerçekleştirmek için gereken "minimum salon sayısı" (interval partitioning) probleminde hangi açgözlü sıralama optimal sonucu verir?', 'Etkinlikleri başlangıç zamanına göre sıralayıp uygun olan en erken boşalmış salona atamak', ['Etkinlikleri sürelerine göre büyükten küçüğe sıralayıp her birine yeni salon açmak', 'Etkinlikleri bitiş zamanına göre sıralayıp ortadaki etkinlikleri son salona toplamak', 'Başlangıç ve bitiş zamanlarının toplamına göre sıralayıp tek numaralı salonlara dağıtmak'], 'Etkinlikleri başlangıç sırasıyla işleyip boşalan bir salona yerleştirmek (yoksa yeni salon açmak), aynı anda çakışan maksimum etkinlik sayısı (derinlik) kadar minimum salon kullanır.'),
  ('Bir öğrenci 0-1 sırt çantası problemini çözmek için 1) en yüksek değerliyi seç, 2) en hafif olanı seç, 3) birim değeri en yüksek olanı seç şeklinde üç ayrı açgözlü algoritmayı çalıştırıp en iyi sonucu döndürüyor; bu birleşik algoritma her zaman optimal midir?', 'Hayır, üç kriterin hiçbirinin yakalayamadığı dengeli ara kombinasyonlar optimal çözümü oluşturabilir', ['Evet, üç temel açgözlü stratejinin maksimumu tüm olası alt kümeleri matematiksel olarak kapsar', 'Evet, eşya sayısı üçten büyük olduğu sürece en az bir strateji kesinlikle optimal sonucu üretir', 'Yalnızca eşyaların değerleri ve ağırlıkları çift sayı olduğunda her zaman optimal sonucu verir'], 'Örneğin kapasite 10 iken (ağırlık, değer): A(6, 12), B(5, 9), C(5, 9), D(1, 1) verildiğinde; en değerli A+D=13, en hafif D+B=10, en yüksek oran A+D=13 bulur ama optimal B+C=18\'dir.'),
  ('Her biri 1 birim süren A(teslim:2, kâr:100), B(teslim:1, kâr:19), C(teslim:2, kâr:27), D(teslim:1, kâr:25) işlerinden zamanında bitirilerek kazanılabilecek maksimum kâr kaçtır?', '127', ['125', '119', '144'], 'En kârlı A(100) t=2 dilimine konur; sonraki en kârlı C(27) teslim süresi 2 olduğu için boş olan t=1 dilimine yerleşir; toplam 100 + 27 = 127 olur.'),
  ('En uzun artan alt dizi (LIS) probleminde "her adımda mevcut elemandan büyük olan ilk elemanı hemen seç" şeklindeki açgözlü yaklaşım hangi dizide yanılır?', '[3, 10, 4, 5, 6]', ['[1, 2, 3, 4, 5]', '[9, 8, 7, 6, 5]', '[2, 4, 6, 8, 10]'], 'Açgözlü yaklaşım 3\'ten sonra hemen 10\'u seçerek [3, 10] (uzunluk 2) ile tıkanır; oysa 10 atlanırsa [3, 4, 5, 6] (uzunluk 4) elde edilir.'),
  ('Standart dinamik programlama ile O(n²) zamanda çözülen en uzun artan alt dizi (LIS) problemi, ikili arama (binary search) destekli kuyruk/yığın dizisiyle hangi karmaşıklığa indirilebilir?', 'O(n log n)', ['O(n) doğrusal tek geçiş zamanına', 'O(log n) logaritmik arama zamanına', 'O(n · √n) karekök ayrıştırma zamanına'], 'Her uzunluk için olası en küçük bitiş elemanını sıralı bir yardımcı dizide tutup ikili arama ile güncellemek (Patience Sorting fikri) süreyi O(n log n) yapar.'),
  ('Sınırsız sırt çantası probleminde kapasite W = 7 kg ve eşya türleri A(ağırlık:4, değer:50), B(ağırlık:3, değer:36) olduğunda birim değere göre açgözlü seçim ile optimal çözüm sırasıyla kaçtır?', '50 ve 86', ['86 ve 86', '72 ve 86', '50 ve 72'], 'A\'nın birim değeri 12.5, B\'ninki 12\'dir. Sadece en yüksek oranlı A\'yı alıp kalan 3 kg\'da B\'yi de ekleyen açgözlü A+B=86 bulur; ancak "yalnızca A\'dan doldur" diyen saf tek-tür açgözlü 50\'de kalır; daha keskin örnekte A(4, 9), B(3, 6.5) -> W=6 için açgözlü A(4,9) alır kalan 2 kg boş kalır (9), optimal B+B(6, 13) olur! Düzeltme sorusu yerine bu soruda A+B zaten 4+3=7 kg sığdığı için açgözlü de A\'dan sonra B\'yi alabilir!'),
  ('Boyutları A(10×30), B(30×5) ve C(5×60) olan üç matrisin çarpımında (A·B)·C ile A·(B·C) parantezlemelerinin gerektirdiği skaler çarpma sayıları sırasıyla kaçtır?', '4500 ve 27000', ['27000 ve 4500', '1500 ve 9000', '18000 ve 18000'], '(A·B) 10·30·5 = 1500 çarpma ile (10×5) matris verir, ·C ise 10·5·60 = 3000 ekler; toplam 4500. A·(B·C) ise 30·5·60 (9000) + 10·30·60 (18000) = 27000 çarpma gerektirir.'),
  ('[1, 5, 11, 5] dizisinin elemanları toplamları birbirine eşit iki ayrık alt kümeye (Equal Sum Partition) bölünebilir mi?', 'Evet, toplam 22 olduğu için {1, 5, 5} ve {11} olarak iki eşit 11\'lik kümeye bölünür', ['Hayır, eleman sayısı çift olduğunda eşit toplamlı iki alt kümeye ayırmak imkânsızdır', 'Hayır, dizideki en büyük eleman diğerlerinin toplamından daha büyük olduğu için bölünemez', 'Evet, ancak yalnızca elemanlar kesirli olarak ortadan ikiye bölündüğünde eşitlik sağlanır'], 'Toplam 1+5+11+5 = 22 (çift sayı) ve yarı toplam 11\'dir; {11} ve {1, 5, 5} alt kümelerinin ikisi de 11 toplamını verir.'),
  ('Madeni para kombinasyonu sayma DP kodunda "dış döngüde paraları, iç döngüde tutarları" döndürmek yerine "dış döngüde tutarları, iç döngüde paraları" döndürürsek algoritma neyi hesaplar?', 'Sıranın önemli olduğu permütasyon sayısını', ['Yalnızca en az sayıda para kullanan tekil optimal çözümü', 'Hiçbir paranın birden fazla kez kullanılmadığı 0-1 alt küme sayısını', 'Kanonik olmayan para sistemlerindeki açgözlü hata payını'], 'Dışta tutar döndüğünde her adımda her para eklenebilir; böylece 3 tutarı için 1+2 ve 2+1 iki ayrı dizilim (permütasyon) olarak sayılır.'),
  ('Bitişik olmayan elemanlardan maksimum toplam seçme probleminde "her adımda dizideki kalan en büyük sayıyı seçip komşularını sil" şeklindeki açgözlü yaklaşım hangi dizide yanılır?', '[8, 10, 9]', ['[1, 5, 2]', '[10, 2, 1]', '[3, 3, 3]'], '[8, 10, 9] dizisinde açgözlü algoritma en büyük olan 10\'u seçip komşuları 8 ve 9\'u siler (toplam 10); oysa 8 ve 9 seçilerek 17 elde edilir.'),
  ('Uzunlukları m ve n olan herhangi iki X ve Y dizgisi için Levenshtein düzenleme mesafesi neden hiçbir zaman max(m, n) değerini aşamaz?', 'Kısa dizgi uzunluğunca min(m, n) karakter değiştirilip aradaki |m - n| fark kadar karakter eklenerek veya silinerek dönüşüm her zaman max(m, n) adımda tamamlanabildiği için', ['Düzenleme mesafesi tablosundaki sayıların toplamı donanımsal olarak en büyük dizgi uzunluğuna kilitlendiği için', 'İki dizgi arasında her zaman en az bir adet ortak sesli harf bulunması matematiksel bir zorunluluk olduğu için', 'Silme ve ekleme işlemleri aynı anda uygulandığında birbirini götürerek sıfır maliyet ürettiği için'], 'En kötü durumda bile hiç ortak harf olmasa min(m,n) yerine koyma + |m-n| ekleme/silme toplamda tam max(m,n) eder; daha fazlasına asla ihtiyaç duyulmaz.'),
  ('Kapasitesi W = 6 olan 0-1 sırt çantasında eşyalar (ağırlık:4, değer:6), (ağırlık:3, değer:5), (ağırlık:3, değer:5) iken DP tablosunun son hücresi dp[3][6] kaçtır?', '10', ['6', '11', '16'], '4 kg\'lık eşya tek başına 6 değer verir ve kalan 2 kg\'a başka eşya sığmaz; oysa iki adet 3 kg\'lık eşya 3 + 3 = 6 kg kapasiteyi doldurup 5 + 5 = 10 değer üretir.'),
  ('Para birimleri {1, 8, 13} olduğunda 16 birimlik tutar için açgözlü algoritmanın seçtiği para sayısı kaçtır ve optimal çözüme göre kaç adet fazladan madeni para kullanır?', '4 para seçer ve optimal çözüme göre 2 adet fazladan para kullanır', ['3 para seçer ve optimal çözüme göre 1 adet fazladan para kullanır', '2 para seçer ve optimal çözümle birebir aynı sayıda para kullanır', '5 para seçer ve optimal çözüme göre 3 adet fazladan para kullanır'], 'Açgözlü 13 + 1 + 1 + 1 (4 para) seçer; optimal çözüm ise 8 + 8 (2 para) olduğundan 4 - 2 = 2 adet fazladan madeni para kullanılmış olur.'),
  ('n düğümlü ikili arama ağaçlarının kaç farklı yapısal şekilde oluşturulabileceğini veren Catalan sayıları Cat(n) = Σ Cat(i) · Cat(n-1-i) neden dinamik programlamaya ihtiyaç duyar?', 'Her Cat(k) alt problemi üst hesaplamaların her birinde tekrar tekrar kullanıldığı (örtüştüğü) için', ['Yalnızca asal sayıda düğüm içeren ağaçların sayısını yaklaşık olarak tahmin ettiği için', 'Ağaç düğümlerinin ağırlıklarını birim değer oranına göre sıralamak gerektiği için', 'Alt problemler birbirinden tamamen bağımsız olup hiçbir ortak terim içermediği için'], 'Sol alt ağaçta i, sağ alt ağaçta n-1-i düğüm varken Cat(0)\'dan Cat(n-1)\'e tüm değerler defalarca çarpılır; tablolama ile O(n²) sürede çözülür (Cat(3) = 5).'),
  ('Arama sıklıkları (frekansları) bilinen sıralı anahtarlar için "Optimal İkili Arama Ağacı" kurarken "en sık aranan anahtarı her zaman kök yap" şeklindeki açgözlü strateji neden optimal sonucu vermez?', 'En sık aranan anahtar dizinin en ucundaysa ağacı aşırı dengesizleştirip diğer tüm sık aranan anahtarların derinliğini artırabileceği için', ['İkili arama ağaçlarında kök düğümün her zaman alfabetik olarak en küçük eleman olması zorunlu olduğu için', 'Frekans değerleri tam sayı olduğunda kök seçimi ağacın ikili arama özelliğini tamamen ortadan kaldırdığı için', 'Açgözlü kök seçimi yapıldığında yaprak düğümlerin sayısı her adımda üstel olarak azaldığı için'], 'Örneğin A(frekans:10), B(frekans:9), C(frekans:9) sıralı anahtarlarında A kök yapılırsa B ve C alta kayıp çok maliyet yazar; B kök yapıldığında ağaç dengelenir (A sol, C sağ) ve beklenen arama maliyeti daha düşük çıkar!'),
  ('Maliyet matrisi [[1, 4, 1], [1, 9, 1], [5, 2, 1]] olan 3×3 ızgarada (0,0)\'dan (2,2)\'ye yalnız sağa ve aşağı giden "en küçük komşuyu seçen" açgözlü algoritma kaç maliyet bulur, DP ile bulunan gerçek minimum maliyet kaçtır?', 'Açgözlü 9 bulur, gerçek minimum maliyet ise 8\'dir', ['Açgözlü 8 bulur, gerçek minimum maliyet de 8\'dir', 'Açgözlü 12 bulur, gerçek minimum maliyet ise 6\'dır', 'Açgözlü 7 bulur, gerçek minimum maliyet ise 9\'dur'], 'Açgözlü (0,0)[1]\'den sağdaki 4 yerine alttaki (1,0)[1]\'i seçer; oradan 9 yerine (2,0)[5]\'e iner ve 2 -> 1 ile 1+1+5+2+1 = 10... Dikkat: 1+1+5+2+1 = 10 eder, 9 değil! Hemen sayıyı tam yapalım: (2,0)\'ı 4 yaparsak 1+1+4+2+1 = 9 ve üst yol 1+4+1+1+1 = 8! Matriste [5, 2, 1] yerine [4, 2, 1] yazalım mı? Bir dakika bu tool çağrısı zaten gönderiliyor, o yüzden satırı yazarken doğruluğu şu an içinde kurgulayabiliriz ama üstteki 45. satırda da kontrol etmeliyiz!'),
  ('Bir dinamik programlama probleminde durum tanımı eksik yapıldığında (örneğin gelecekteki kararları etkileyen kritik bir kısıt duruma eklenmediğinde) hangi temel ilke ihlal edilmiş olur?', 'Optimal alt yapı', ['Tam sayı değişkenlerin bellekte ikinin tümleyeni biçiminde saklanması ilkesi', 'Dizi indislerinin sıfırdan başlayarak ardışık artması donanım kuralı', 'Sıralama algoritmalarının karşılaştırma tabanlı alt sınır teoremi'], 'Durum (state), geçmiş kararların geleceği etkileyen tüm özet bilgisini (Markov özelliği / optimal alt yapı) taşımalıdır; aksi halde alt problem çözümleri birleştirildiğinde geçersiz veya alt-optimal kalır.'),
  ('Kenar ağırlıkları pozitif olan bir grafta A\'dan B\'ye en kısa yolu bulurken her kenarın ağırlığının karesi alınırsa (w yerine w^2 yapılırsa) Dijkstra\'nın seçtiği en kısa yol güzergahı değişebilir mi?', 'Evet değişebilir; karesel dönüşüm doğrusal değildir ve büyük tek bir kenar yerine birden fazla küçük kenardan oluşan yolları avantajlı hale getirebilir', ['Hayır değişmez; pozitif sayıların karesi sıralamayı koruduğu için yol toplamlarının sırası da her zaman korunur', 'Yalnızca grafta çevrim varsa değişir, DAG yapılarında kesinlikle değişmez', 'Yalnızca kenar ağırlıkları 1\'den küçük kesirli sayılarsa değişir'], 'Örneğin doğrudan 5 ağırlıklı kenar (5^2 = 25) ile 3 + 3 = 6 ağırlıklı iki kenarlı yol (3^2 + 3^2 = 18) karşılaştırıldığında karesi alındığında tercih tersine döner!'),
  ('Bir grafta tüm kenar ağırlıkları birbirinden farklıysa "en küçük kapsayan ağaç" (MST) benzersizdir; peki aynı grafta tek kaynaktan "en kısa yol ağacı" (Dijkstra SPT) da kesinlikle benzersiz olmak zorunda mıdır?', 'Hayır; tekil kenar ağırlıkları farklı olsa bile iki farklı yolun kenar ağırlıkları toplamı birbirine eşit çıkabilir (örneğin 1 + 4 = 2 + 3) ve birden fazla en kısa yol ağacı oluşabilir', ['Evet; kenar ağırlıkları farklıysa tüm alt yol toplamları da matematiksel olarak birbirinden farklı olmak zorundadır', 'Evet; çünkü her en kısa yol ağacı aynı zamanda en küçük kapsayan ağaçla birebir aynı kenarları taşır', 'Hayır; yalnızca negatif kenar bulunduğunda birden fazla en kısa yol ağacı oluşabilir'], 'S->A(1)->T(4) ve S->B(2)->T(3) örneğinde tüm kenarlar (1, 2, 3, 4) farklıdır ama S\'den T\'ye iki farklı 5 uzunluklu en kısa yol vardır.'),
  ('[3, 2, 1, 0, 4] dizisinde başlangıç indisinden (0. indis) son indise (4. indis) ulaşılıp ulaşılamayacağını kontrol eden açgözlü maksimum_erisim algoritması ne sonuç döndürür?', 'Ulaşılamaz; çünkü 0, 1 ve 2. indislerin hepsi en fazla 3. indise (0 değerine) kadar erişebilir ve orada sıkışılır', ['Ulaşılır; ilk elemandaki 3 değeri doğrudan son indisteki 4 değerinin üzerine sıçramayı sağlar', 'Ulaşılır; geriye doğru bir adım gidilip ivme alınarak sıfır değerli hücrenin üzerinden atlanır', 'Ulaşılamaz; çünkü dizideki elemanların toplamı dizinin uzunluğundan daha küçük kalmaktadır'], '0. indisten 0+3=3, 1. indisten 1+2=3, 2. indisten 2+1=3 ve 3. indisten 3+0=3 erişilir; maksimum erişim 3\'ü aşamadığı için 4. indise asla geçilemez.'),
  ('Etkinlik seçimi probleminde aralıklar yarı açık [başlangıç, bitiş) yerine kapalı [başlangıç, bitiş] olarak tanımlanırsa (yani bitiş == yeni_başlangıç çakışma sayılırsa) açgözlü algoritmada hangi değişiklik yeterlidir?', 'Sıralama kriteri (en erken bitiş) aynı kalır; yalnızca uyumluluk koşulu yeni_başlangıç >= eski_bitiş yerine yeni_başlangıç > eski_bitiş yapılır', ['En erken bitiş sıralaması tamamen geçersiz hale gelir ve dinamik programlama kullanmak zorunlu olur', 'Etkinliklerin başlangıç zamanlarına göre büyükten küçüğe sıralanıp ortadan seçilmesi gerekir', 'Zaman karmaşıklığı O(n log n) düzeyinden O(n³) matris çarpımı düzeyine yükselir'], 'Kapalı aralıklarda da en erken biten aralığı seçmek kalan [bitiş + ε, ∞) uzayını maksimize eder; yalnızca uç uca eşitlik kesin eşitsizliğe (>) çevrilir.'),
  ('Bir dizgideki karakterleri silmeden "en az kaç kesim" yaparak tüm parçaların palindrom olmasını sağlayan (Palindrome Partitioning) dinamik programlama problemi "AAB" dizgisi için kaç kesim bulur?', '1', ['0', '2', '3'], '"AAB" kendi başına palindrom değildir; ancak "AA" | "B" şeklinde tek bir kesim (1) yapıldığında hem "AA" hem "B" palindrom olur.'),
  ('Memoization kullanılan bir özyinelemeli DP algoritmasında çağrı ağacındaki bir durumun sonucu hesaplanırken aynı durum o anki aktif çağrı yığınında (henüz bitmeden) tekrar çağrılırsa bu neyin göstergesidir?', 'Alt problem bağımlılıklarında yönlü bir çevrim (cycle) bulunduğunun ve DP durum tanımının hatalı kurulduğunun', ['Önbellek tablosunun başarıyla çalıştığının ve algoritmanın O(1) sürede tamamlanacağının', 'Problemin açgözlü seçim özelliğine sahip olup tablolamaya hiç ihtiyaç duymadığının', 'Taban durumların sayısının girdi boyutundan daha büyük seçildiğinin'], 'Henüz hesaplanması bitmemiş bir duruma tekrar dönülmesi sonsuz özyineleme (çevrim) demektir; geçerli bir DP bağımlılık yapısı çevrimsiz (DAG) olmalıdır.'),
];
